            .ThenInclude(r => r!.Spielstaette)
            .Where(v => v.Id == id)
            .Select(v => new VeranstaltungDetailDto(
                v.Id,
                v.Titel,
                v.Beschreibung,
                v.DauerMinuten,
                v.Altersfreigabe,
                v.Raum!.Spielstaette!.Name,
                v.Raum!.Name,
                v.Zeitpunkt))
            .FirstOrDefaultAsync();
    }
}

